  --bg-color: #0f172a;
  --surface-color: #1e293b;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --accent-color: #38bdf8;
  --accent-hover: #0ea5e9;
  --error-color: #ef4444;
  --focus-ring: 0 0 0 3px rgba(56, 189, 248, 0.5);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--accent-color);
  color: #000;
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
}

header {
  background-color: rgba(15, 23, 42, 0.9);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid #334155;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 4rem;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover, .nav-links a:focus {
  color: var(--accent-color);
  outline: none;
}

.nav-actions {
  display: flex;
  gap: 1rem;
}

.nav-actions .btn {
  padding: 0.5rem;
  font-size: 1.125rem;
}

.hero {
  padding: 6rem 0;
  text-align: center;
  background: linear-gradient(to bottom, #1e293b, #0f172a);
}

.hero h1 {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
  line-height: 1.1;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 2rem;
}

.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s;
  cursor: pointer;
  border: none;
}

.btn-primary {
  background-color: var(--accent-color);
  color: #0f172a;
}

.btn-primary:hover, .btn-primary:focus {
  background-color: var(--accent-hover);
  box-shadow: var(--focus-ring);
  outline: none;
}

section {
  padding: 4rem 0;
}

.section-title {
  font-size: 2rem;
  margin-bottom: 2rem;
  text-align: center;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.card {
  background-color: var(--surface-color);
  border-radius: 0.75rem;
  overflow: hidden;
  transition: transform 0.2s;
  border: 1px solid #334155;
}

.card:hover {
  transform: translateY(-4px);
}

.card-img {
  width: 100%;
  aspect-ratio: 4/5;
  background-color: #334155;
  object-fit: cover;
}

.card-content {
  padding: 1.5rem;
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.card-price {
  font-weight: 700;
  color: var(--accent-color);
  font-size: 1.125rem;
}

.deal-badge {
  background-color: var(--error-color);
  color: white;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  font-weight: 700;
  margin-left: 0.5rem;
}

.editorial {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

@media (max-width: 768px) {
  .editorial {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .hero h1 {
    font-size: 2.5rem;
  }
}

.editorial-img {
  width: 100%;
  border-radius: 1rem;
  aspect-ratio: 16/9;
  background-color: #334155;
  object-fit: cover;
}

footer {
  background-color: #020617;
  padding: 4rem 0 2rem;
  border-top: 1px solid #334155;
  color: var(--text-secondary);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-title {
  color: var(--text-primary);
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: 0.75rem;
}

.footer-links a {
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.2s;
}

.footer-links a:hover {
  color: var(--text-primary);
}

.copyright {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid #1e293b;
  font-size: 0.875rem;
}

/* Accessibility focus styles */
:focus-visible {
  outline: 2px solid var(--accent-color);
  outline-offset: 4px;
}
